                (seq[i] == 'U' && seq[j] == 'A') ||
                (seq[i] == 'T' && seq[j] == 'A') ||
                (seq[i] == 'G' && seq[j] == 'C') ||
                (seq[i] == 'C' && seq[j] == 'G')) {
                case3 += 1;
            }

            int case4 = 0;
            for (int k = i+1; k < j; k++) {
                int split_val = table[i][k] + table[k+1][j];
                if (split_val > case4) {
                    case4 = split_val;
                }
            }

            int max_val = case1;
            if (case2 > max_val) max_val = case2;
            if (case3 > max_val) max_val = case3;
            if (case4 > max_val) max_val = case4;

            table[i][j] = max_val;
        }
    }
}
